<?php
namespace App\Http\Controllers\Crm; use App\Http\Controllers\Controller; use App\Models\{LeadFollowup,User}; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\View\View;
class FollowupController extends Controller { public function index(Request $r):View{$q=LeadFollowup::with(['lead','client','assignee'])->orderBy('follow_up_date');if($r->filled('scope')){$q->{$r->scope==='overdue'?'whereDate':'whereDate'}('follow_up_date',$r->scope==='overdue'?'<':'=',today());}return view('crm.followups.index',['followups'=>$q->paginate(20),'users'=>User::orderBy('name')->get()]);} public function update(Request $r,LeadFollowup $followup):RedirectResponse{$r->validate(['status'=>'required|in:pending,completed,cancelled,missed']);$followup->update($r->only('status'));return back()->with('toast',['type'=>'success','message'=>'Follow-up updated.']);}}
